/* ============================================================================
   D. MERGE KE MASTER_PERTANYAAN

   WHEN MATCHED dibatasi pada baris berpenanda benih. Pertanyaan yang ditulis
   sendiri tim — meski kodenya kebetulan sama — tidak ditimpa.
   ============================================================================ */

MERGE dbo.N_WEB_CAREERS_Master_Pertanyaan AS t
USING dbo.NWC_Stage_Bank AS s
   ON t.Konteks = 'SKRINING' AND t.Kode = s.Kode
 WHEN NOT MATCHED BY TARGET THEN
    INSERT (Kode, Konteks, Kelompok, Sub_Kelompok, Jenis, Prioritas, Tipe, Label, Bantuan,
            Opsi, Skala_Min, Skala_Max, Label_Min, Label_Max, Bobot_Bawaan,
            Knockout_Operator, Knockout_Nilai, Knockout_Pesan,
            Flag_Wajib_Bawaan, Flag_Catatan_Bawaan, Durasi_Detik,
            Jawaban_Diharapkan, Red_Flag, Pertanyaan_Lanjutan, Kriteria_Nilai,
            Flag_Sistem, Flag_Aktif, Urutan, Versi, Status_Tinjau, Pemilik,
            Created_At, Created_By, Updated_At, Updated_By)
    VALUES (s.Kode, 'SKRINING', s.Kelompok, s.Sub_Kelompok, s.Jenis, s.Prioritas, s.Tipe, s.Label, s.Bantuan,
            s.Opsi, s.Skala_Min, s.Skala_Max, s.Label_Min, s.Label_Max, s.Bobot_Bawaan,
            s.Knockout_Operator, s.Knockout_Nilai, s.Knockout_Pesan,
            s.Flag_Wajib_Bawaan, s.Flag_Catatan_Bawaan, s.Durasi_Detik,
            s.Jawaban_Diharapkan, s.Red_Flag, s.Pertanyaan_Lanjutan, s.Kriteria_Nilai,
            'Y', 'Y', s.Urutan, 1, 'APPROVED', 'Talent Acquisition',
            GETDATE(), 'SISTEM(bank-isi)', GETDATE(), 'SISTEM(bank-isi)')
 WHEN MATCHED AND t.Created_By = 'SISTEM(bank-isi)' THEN
    UPDATE SET t.Kelompok = s.Kelompok, t.Sub_Kelompok = s.Sub_Kelompok,
               t.Jenis = s.Jenis, t.Prioritas = s.Prioritas, t.Tipe = s.Tipe,
               t.Label = s.Label, t.Bantuan = s.Bantuan, t.Opsi = s.Opsi,
               t.Skala_Min = s.Skala_Min, t.Skala_Max = s.Skala_Max,
               t.Label_Min = s.Label_Min, t.Label_Max = s.Label_Max,
               t.Bobot_Bawaan = s.Bobot_Bawaan,
               t.Knockout_Operator = s.Knockout_Operator,
               t.Knockout_Nilai = s.Knockout_Nilai,
               t.Knockout_Pesan = s.Knockout_Pesan,
               t.Flag_Wajib_Bawaan = s.Flag_Wajib_Bawaan,
               t.Flag_Catatan_Bawaan = s.Flag_Catatan_Bawaan,
               t.Durasi_Detik = s.Durasi_Detik,
               t.Jawaban_Diharapkan = s.Jawaban_Diharapkan,
               t.Red_Flag = s.Red_Flag,
               t.Pertanyaan_Lanjutan = s.Pertanyaan_Lanjutan,
               t.Kriteria_Nilai = s.Kriteria_Nilai,
               t.Urutan = s.Urutan,
               t.Updated_At = GETDATE(), t.Updated_By = 'SISTEM(bank-isi)';
GO


/* ============================================================================
   E. SEGARKAN PENGIKATAN TAG

   Yang dibuang HANYA pengikatan berpenanda benih. Tag yang dipasang tim lewat
   layar tetap bertahan — kalau ikut dibuang, pekerjaan mereka hilang setiap
   kali berkas ini dijalankan ulang.
   ============================================================================ */

DELETE pt
  FROM dbo.N_WEB_CAREERS_Master_Pertanyaan_Tag AS pt
  JOIN dbo.N_WEB_CAREERS_Master_Pertanyaan AS p ON p.Id_Master_Pertanyaan = pt.Master_Pertanyaan_Id
 WHERE pt.Created_By = 'SISTEM(bank-isi)'
   AND p.Konteks = 'SKRINING'
   AND EXISTS (SELECT 1 FROM dbo.NWC_Stage_Bank b WHERE b.Kode = p.Kode);
GO

SELECT p.Id_Master_Pertanyaan, g.Id_Master_Tag, g.Dimensi, g.Kode, GETDATE(), 'SISTEM(bank-isi)'
  FROM dbo.NWC_Stage_BankTag AS bt
  JOIN dbo.N_WEB_CAREERS_Master_Pertanyaan AS p
    ON p.Konteks = 'SKRINING' AND p.Kode = bt.Kode
  JOIN dbo.N_WEB_CAREERS_Master_Tag AS g
    ON g.Dimensi = bt.Dimensi AND g.Kode = bt.Tag
 WHERE NOT EXISTS (
       SELECT 1 FROM dbo.N_WEB_CAREERS_Master_Pertanyaan_Tag AS x
        WHERE x.Master_Pertanyaan_Id = p.Id_Master_Pertanyaan
          AND x.Master_Tag_Id = g.Id_Master_Tag);
GO


/* ============================================================================
   F. PENSIUNKAN BENIH AWAL

   Berkas 2026-08-24-bank-pertanyaan.sql dulu menanam 14 pertanyaan pemula,
   waktu repositori penuh ini belum ada. Keempat belasnya kini punya padanan
   yang lebih lengkap — 'bersedia_relokasi' digantikan 'avl_relokasi',
   'gaji_harapan' oleh 'cmp_gaji_harapan', dan seterusnya — lengkap dengan
   rubrik penilaian, penanda risiko, dan pengikatan tag.

   TIDAK DIHAPUS, hanya dinonaktifkan. Menghapusnya akan memutus jejak template
   mana pun yang sudah terlanjur menariknya; menonaktifkannya cukup untuk
   membuatnya berhenti ditawarkan saat menyusun template baru.

   Yang sudah disunting tim (Updated_By bukan penanda sistem) dibiarkan apa
   adanya — itu berarti seseorang memang sengaja memakainya.
   ============================================================================ */

UPDATE dbo.N_WEB_CAREERS_Master_Pertanyaan
   SET Flag_Aktif = 'N',
       Bantuan = ISNULL(Bantuan + ' ', '') + N'[Digantikan repositori penuh — pakai padanan barunya.]',
       Updated_At = GETDATE(),
       Updated_By = 'SISTEM(bank-isi)'
 WHERE Konteks = 'SKRINING'
   AND Created_By = 'SISTEM(bank-pertanyaan)'
   AND ISNULL(Updated_By, '') IN ('SISTEM(bank-pertanyaan)', '')
   AND Flag_Aktif = 'Y';
GO

/* Sisanya — yang terlanjur disunting tim — tetap aktif, tapi diberi tag
   GENERAL supaya tidak ada satu pun pertanyaan yang tak terjangkau penyaring. */
SELECT p.Id_Master_Pertanyaan, g.Id_Master_Tag, g.Dimensi, g.Kode, GETDATE(), 'SISTEM(bank-isi)'
  FROM dbo.N_WEB_CAREERS_Master_Pertanyaan AS p
 CROSS JOIN dbo.N_WEB_CAREERS_Master_Tag AS g
 WHERE p.Konteks = 'SKRINING'
   AND g.Dimensi = 'JOB_FAMILY' AND g.Kode = 'GENERAL'
   AND NOT EXISTS (
       SELECT 1 FROM dbo.N_WEB_CAREERS_Master_Pertanyaan_Tag AS x
        WHERE x.Master_Pertanyaan_Id = p.Id_Master_Pertanyaan AND x.Dimensi = 'JOB_FAMILY');
GO


/* ============================================================================
   G. VERIFIKASI
   ============================================================================ */

SELECT 'Pertanyaan di bank' AS Pemeriksaan,
       CAST(COUNT(*) AS VARCHAR(10)) AS Jumlah
  FROM dbo.N_WEB_CAREERS_Master_Pertanyaan WHERE Konteks = 'SKRINING'
UNION ALL
SELECT 'Pengikatan tag', CAST(COUNT(*) AS VARCHAR(10))
  FROM dbo.N_WEB_CAREERS_Master_Pertanyaan_Tag
UNION ALL
SELECT 'Pertanyaan tanpa tag job family',
       CAST(COUNT(*) AS VARCHAR(10))
  FROM dbo.N_WEB_CAREERS_Master_Pertanyaan p
 WHERE p.Konteks = 'SKRINING'
   AND NOT EXISTS (SELECT 1 FROM dbo.N_WEB_CAREERS_Master_Pertanyaan_Tag x
                    WHERE x.Master_Pertanyaan_Id = p.Id_Master_Pertanyaan AND x.Dimensi = 'JOB_FAMILY');
GO

SELECT Kelompok, COUNT(*) AS Jumlah
  FROM dbo.N_WEB_CAREERS_Master_Pertanyaan
 WHERE Konteks = 'SKRINING'
 GROUP BY Kelompok
 ORDER BY COUNT(*) DESC;
GO

SELECT pt.Tag_Kode AS Job_Family, COUNT(*) AS Pertanyaan
  FROM dbo.N_WEB_CAREERS_Master_Pertanyaan_Tag pt
 WHERE pt.Dimensi = 'JOB_FAMILY'
 GROUP BY pt.Tag_Kode
 ORDER BY COUNT(*) DESC;
GO

IF OBJECT_ID('dbo.NWC_Stage_Bank', 'U') IS NOT NULL DROP TABLE dbo.NWC_Stage_Bank;
IF OBJECT_ID('dbo.NWC_Stage_BankTag', 'U') IS NOT NULL DROP TABLE dbo.NWC_Stage_BankTag;
GO
