(N'avl_relokasi', N'Ketersediaan', N'Penempatan', N'AVAILABILITY', N'MANDATORY', N'RADIO', N'Apakah Anda bersedia ditempatkan di luar kota domisili?', N'Isi ambang gugurnya per template — ada loker yang memang tidak menuntut relokasi.', N'[{"nilai": "YA", "label": "Ya, bersedia", "skor": 10}, {"nilai": "NEGO", "label": "Bisa dirundingkan", "skor": 5}, {"nilai": "TIDAK", "label": "Tidak bersedia", "skor": 0}]', NULL, NULL, NULL, NULL, 2, NULL, NULL, NULL, 'Y', 'T', 30, NULL, NULL, N'Apakah ada kota yang tidak memungkinkan bagi Anda?', N'{"1": "Jawaban tidak konsisten dengan berkas lamarannya.", "2": "Ragu-ragu atau perlu banyak dipancing untuk menjawab.", "3": "Menjawab dengan jelas dan sesuai berkas.", "4": "Jelas, sesuai, dan menambahkan konteks yang berguna.", "5": "Sangat jelas, sesuai, dan proaktif menjelaskan hal yang mungkin dipertanyakan."}', 46),
(N'avl_kota_pantangan', N'Ketersediaan', N'Penempatan', N'AVAILABILITY', N'CONDITIONAL', N'TEXTAREA', N'Adakah lokasi penempatan yang tidak memungkinkan bagi Anda, dan apa alasannya?', N'Ditanyakan setelah kandidat menjawab "bisa dirundingkan". Alasannya menentukan apakah masih bisa dicarikan jalan.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'T', 'T', 40, NULL, NULL, NULL, N'{"1": "Jawaban tidak konsisten dengan berkas lamarannya.", "2": "Ragu-ragu atau perlu banyak dipancing untuk menjawab.", "3": "Menjawab dengan jelas dan sesuai berkas.", "4": "Jelas, sesuai, dan menambahkan konteks yang berguna.", "5": "Sangat jelas, sesuai, dan proaktif menjelaskan hal yang mungkin dipertanyakan."}', 47),
(N'avl_shift', N'Ketersediaan', N'Jam Kerja', N'AVAILABILITY', N'CONDITIONAL', N'RADIO', N'Apakah Anda bersedia bekerja dengan sistem giliran (shift)?', N'Hanya untuk posisi yang memang bergiliran. Menanyakannya di posisi kantoran membingungkan kandidat.', N'[{"nilai": "YA", "label": "Ya, bersedia", "skor": 10}, {"nilai": "NEGO", "label": "Bisa dirundingkan", "skor": 5}, {"nilai": "TIDAK", "label": "Tidak bersedia", "skor": 0}]', NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL, 'T', 'T', 25, NULL, NULL, N'Apakah Anda pernah bekerja dengan sistem giliran sebelumnya?', N'{"1": "Tidak menjawab situasi nyata; hanya opini umum atau normatif.", "2": "Menyebut situasi, tapi peran dirinya kabur dan hasilnya tidak jelas.", "3": "Situasi, tindakan, dan hasil tersampaikan cukup runtut.", "4": "Runtut dan spesifik; peran dirinya jelas, hasilnya terukur.", "5": "Sangat spesifik dan terukur; menyebut dampak, pembelajaran, dan apa yang akan ia ubah."}', 48),
(N'avl_lembur', N'Ketersediaan', N'Jam Kerja', N'AVAILABILITY', N'RECOMMENDED', N'RADIO', N'Bagaimana kesediaan Anda bila sesekali harus bekerja di luar jam kerja normal?', N'Sampaikan apa adanya. Kandidat yang menyanggupi hal yang tidak mungkin ia jalani akan mundur di bulan kedua.', N'[{"nilai": "BISA", "label": "Bisa, selama direncanakan", "skor": 10}, {"nilai": "TERBATAS", "label": "Bisa sesekali, dengan pemberitahuan", "skor": 7}, {"nilai": "SULIT", "label": "Sulit karena kewajiban lain", "skor": 3}]', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'T', 'T', 30, NULL, NULL, NULL, N'{"1": "Tidak menjawab situasi nyata; hanya opini umum atau normatif.", "2": "Menyebut situasi, tapi peran dirinya kabur dan hasilnya tidak jelas.", "3": "Situasi, tindakan, dan hasil tersampaikan cukup runtut.", "4": "Runtut dan spesifik; peran dirinya jelas, hasilnya terukur.", "5": "Sangat spesifik dan terukur; menyebut dampak, pembelajaran, dan apa yang akan ia ubah."}', 49),
(N'avl_perjalanan_dinas', N'Ketersediaan', N'Perjalanan', N'AVAILABILITY', N'CONDITIONAL', N'RADIO', N'Apakah Anda bersedia melakukan perjalanan dinas?', N'Sebutkan perkiraan frekuensinya supaya jawabannya berdasar.', N'[{"nilai": "SERING", "label": "Ya, termasuk yang sering", "skor": 10}, {"nilai": "SESEKALI", "label": "Ya, sesekali", "skor": 7}, {"nilai": "TIDAK", "label": "Tidak bisa", "skor": 0}]', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'T', 'T', 25, NULL, NULL, N'Berapa lama perjalanan dinas yang masih nyaman bagi Anda?', N'{"1": "Tidak menjawab situasi nyata; hanya opini umum atau normatif.", "2": "Menyebut situasi, tapi peran dirinya kabur dan hasilnya tidak jelas.", "3": "Situasi, tindakan, dan hasil tersampaikan cukup runtut.", "4": "Runtut dan spesifik; peran dirinya jelas, hasilnya terukur.", "5": "Sangat spesifik dan terukur; menyebut dampak, pembelajaran, dan apa yang akan ia ubah."}', 50),
(N'avl_pola_kerja', N'Ketersediaan', N'Pola Kerja', N'AVAILABILITY', N'RECOMMENDED', N'SELECT', N'Pola kerja seperti apa yang Anda harapkan?', N'Selisih di sini adalah penyebab batalnya penawaran yang paling sering terjadi belakangan. Sampaikan kebijakan sebenarnya sekarang juga.', N'[{"nilai": "WFO", "label": "Sepenuhnya di kantor", "skor": null}, {"nilai": "HYBRID", "label": "Campuran kantor & rumah", "skor": null}, {"nilai": "WFH", "label": "Sepenuhnya dari rumah", "skor": null}, {"nilai": "FLEKSIBEL", "label": "Mengikuti kebijakan perusahaan", "skor": null}]', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'T', 'T', 25, NULL, NULL, NULL, N'{"1": "Tidak menjawab situasi nyata; hanya opini umum atau normatif.", "2": "Menyebut situasi, tapi peran dirinya kabur dan hasilnya tidak jelas.", "3": "Situasi, tindakan, dan hasil tersampaikan cukup runtut.", "4": "Runtut dan spesifik; peran dirinya jelas, hasilnya terukur.", "5": "Sangat spesifik dan terukur; menyebut dampak, pembelajaran, dan apa yang akan ia ubah."}', 51),
(N'avl_status_kepegawaian', N'Ketersediaan', N'Status', N'ELIGIBILITY', N'MANDATORY', N'RADIO', N'Apakah Anda bersedia dengan status kepegawaian yang ditawarkan untuk posisi ini?', N'Sebutkan statusnya lebih dulu — kontrak, tetap, atau harian. Kandidat tidak bisa menjawab pertanyaan yang belum ia ketahui isinya.', N'[{"nilai": "YA", "label": "Ya, bersedia", "skor": 10}, {"nilai": "TANYA", "label": "Perlu penjelasan lebih dulu", "skor": 5}, {"nilai": "TIDAK", "label": "Tidak bersedia", "skor": 0}]', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Y', 'T', 30, NULL, NULL, NULL, N'{"1": "Tidak menjawab situasi nyata; hanya opini umum atau normatif.", "2": "Menyebut situasi, tapi peran dirinya kabur dan hasilnya tidak jelas.", "3": "Situasi, tindakan, dan hasil tersampaikan cukup runtut.", "4": "Runtut dan spesifik; peran dirinya jelas, hasilnya terukur.", "5": "Sangat spesifik dan terukur; menyebut dampak, pembelajaran, dan apa yang akan ia ubah."}', 52),
(N'avl_ikatan_dinas', N'Ketersediaan', N'Status', N'ELIGIBILITY', N'RECOMMENDED', N'BOOLEAN', N'Apakah Anda sedang terikat kontrak, ikatan dinas, atau perjanjian tidak bersaing dengan pihak lain?', N'Sering terlewat dan baru ketahuan saat penawaran. Ikatan dinas beasiswa dan perjanjian non-kompetisi bisa membatalkan seluruh proses.', N'[{"nilai": "YA", "label": "Ya", "skor": 10}, {"nilai": "TIDAK", "label": "Tidak", "skor": 0}]', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'T', 'T', 30, NULL, N'Terikat perjanjian yang berbenturan langsung dengan posisi ini.', N'Sampai kapan, dan apa konsekuensinya bila diakhiri lebih awal?', N'{"1": "Jawaban tidak konsisten dengan berkas lamarannya.", "2": "Ragu-ragu atau perlu banyak dipancing untuk menjawab.", "3": "Menjawab dengan jelas dan sesuai berkas.", "4": "Jelas, sesuai, dan menambahkan konteks yang berguna.", "5": "Sangat jelas, sesuai, dan proaktif menjelaskan hal yang mungkin dipertanyakan."}', 53),
(N'avl_jadwal_kuliah', N'Ketersediaan', N'Magang', N'AVAILABILITY', N'CONDITIONAL', N'TEXTAREA', N'Bagaimana jadwal kuliah Anda, dan berapa hari dalam seminggu Anda bisa hadir?', N'Khusus magang. Jadwal yang tidak dibicarakan di muka berujung pada peserta yang jarang hadir.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'T', 'T', 40, NULL, NULL, NULL, N'{"1": "Jawaban tidak konsisten dengan berkas lamarannya.", "2": "Ragu-ragu atau perlu banyak dipancing untuk menjawab.", "3": "Menjawab dengan jelas dan sesuai berkas.", "4": "Jelas, sesuai, dan menambahkan konteks yang berguna.", "5": "Sangat jelas, sesuai, dan proaktif menjelaskan hal yang mungkin dipertanyakan."}', 54),
