(N'cmp_tunjangan_sekarang', N'Kompensasi', N'Sekarang', N'COMPENSATION', N'RECOMMENDED', N'TEXTAREA', N'Selain gaji pokok, tunjangan apa saja yang Anda terima sekarang?', N'Penting untuk membandingkan paket secara utuh — transport, makan, kesehatan, bonus tahunan.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'T', 'T', 45, NULL, NULL, NULL, N'{"1": "Jawaban tidak konsisten dengan berkas lamarannya.", "2": "Ragu-ragu atau perlu banyak dipancing untuk menjawab.", "3": "Menjawab dengan jelas dan sesuai berkas.", "4": "Jelas, sesuai, dan menambahkan konteks yang berguna.", "5": "Sangat jelas, sesuai, dan proaktif menjelaskan hal yang mungkin dipertanyakan."}', 56),
(N'cmp_gaji_harapan', N'Kompensasi', N'Harapan', N'COMPENSATION', N'MANDATORY', N'CURRENCY', N'Berapa gaji harapan Anda untuk posisi ini?', N'Ambang gugurnya diisi PER TEMPLATE — rentangnya berbeda tiap MPP, dan bawaan yang salah lebih berbahaya daripada tidak ada bawaan.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Y', 'T', 40, N'Angka yang jelas, bukan "mengikuti kebijakan perusahaan".', N'Menolak menyebut angka sama sekali, atau angkanya jauh di atas rentang tanpa alasan.', N'Apa dasar Anda menyebut angka tersebut?', N'{"1": "Jawaban tidak konsisten dengan berkas lamarannya.", "2": "Ragu-ragu atau perlu banyak dipancing untuk menjawab.", "3": "Menjawab dengan jelas dan sesuai berkas.", "4": "Jelas, sesuai, dan menambahkan konteks yang berguna.", "5": "Sangat jelas, sesuai, dan proaktif menjelaskan hal yang mungkin dipertanyakan."}', 57),
(N'cmp_gaji_fleksibel', N'Kompensasi', N'Harapan', N'COMPENSATION', N'RECOMMENDED', N'RADIO', N'Apakah angka tersebut masih bisa dirundingkan?', N'Ditanyakan sesudah angkanya disebut, bukan sebelum.', N'[{"nilai": "YA", "label": "Ya, bisa dirundingkan", "skor": 10}, {"nilai": "TERBATAS", "label": "Sedikit, dalam batas tertentu", "skor": 6}, {"nilai": "TIDAK", "label": "Tidak, itu angka minimum saya", "skor": 2}]', NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL, 'T', 'T', 25, NULL, NULL, NULL, N'{"1": "Tidak menjawab situasi nyata; hanya opini umum atau normatif.", "2": "Menyebut situasi, tapi peran dirinya kabur dan hasilnya tidak jelas.", "3": "Situasi, tindakan, dan hasil tersampaikan cukup runtut.", "4": "Runtut dan spesifik; peran dirinya jelas, hasilnya terukur.", "5": "Sangat spesifik dan terukur; menyebut dampak, pembelajaran, dan apa yang akan ia ubah."}', 58),
(N'cmp_gaji_minimum', N'Kompensasi', N'Harapan', N'COMPENSATION', N'CONDITIONAL', N'CURRENCY', N'Berapa angka minimum yang membuat Anda bersedia menerima tawaran ini?', N'Ditanyakan hanya bila harapannya di atas rentang. Menanyakannya lebih awal justru menurunkan penawaran yang bisa diberikan.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'T', 'T', 30, NULL, NULL, NULL, N'{"1": "Jawaban tidak konsisten dengan berkas lamarannya.", "2": "Ragu-ragu atau perlu banyak dipancing untuk menjawab.", "3": "Menjawab dengan jelas dan sesuai berkas.", "4": "Jelas, sesuai, dan menambahkan konteks yang berguna.", "5": "Sangat jelas, sesuai, dan proaktif menjelaskan hal yang mungkin dipertanyakan."}', 59),
(N'cmp_prioritas_paket', N'Kompensasi', N'Harapan', N'COMPENSATION', N'OPTIONAL', N'TEXTAREA', N'Selain gaji, komponen apa yang paling penting bagi Anda dalam sebuah paket kerja?', N'Membuka ruang negosiasi non-gaji: cuti, pelatihan, asuransi, jenjang.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'T', 'T', 40, NULL, NULL, NULL, N'{"1": "Tidak punya alasan selain kebutuhan pribadi jangka pendek.", "2": "Alasan umum yang bisa dipakai untuk perusahaan mana pun.", "3": "Menyebut alasan yang relevan dengan posisi atau industrinya.", "4": "Menunjukkan ia sudah mencari tahu tentang perusahaan dan perannya.", "5": "Menghubungkan posisi ini dengan rencana kariernya secara meyakinkan dan spesifik."}', 60);
