(N'bhv_belajar_kembangkan_tim', N'Perilaku', N'Kecepatan Belajar', N'BEHAVIORAL', N'RECOMMENDED', N'TEXTAREA', N'Ceritakan bagaimana Anda mengembangkan kemampuan anggota tim Anda.', N'Yang dinilai: apakah ada contoh orang nyata yang berkembang, bukan program pelatihan di atas kertas.', NULL, NULL, NULL, NULL, NULL, 2, NULL, NULL, NULL, 'T', 'T', 110, N'Menyebut orang tertentu, apa yang dikembangkan, dan hasilnya sekarang.', N'Hanya menyebut "saya kirim mereka pelatihan".', N'Ada yang kemudian naik jabatan atau pindah ke peran lebih besar?', N'{"1": "Bercerita sebagai pelaksana, bukan sebagai pengarah tim.", "2": "Menyebut peran memimpin, tapi tidak menjelaskan bagaimana ia mengambil keputusan.", "3": "Menjelaskan keputusan dan dampaknya pada tim.", "4": "Menjelaskan pertimbangan, komunikasi ke tim, dan hasil terukurnya.", "5": "Menunjukkan kematangan: mengakui trade-off, mengelola resistensi, dan mengembangkan orangnya."}', 106),
(N'bhv_belajar_budaya_belajar', N'Perilaku', N'Kecepatan Belajar', N'BEHAVIORAL', N'RECOMMENDED', N'TEXTAREA', N'Bagaimana Anda membangun kebiasaan belajar di unit yang Anda pimpin?', N'Cari mekanisme yang bertahan tanpa kehadirannya — bukan inisiatif yang berhenti saat ia sibuk.', NULL, NULL, NULL, NULL, NULL, 2, NULL, NULL, NULL, 'T', 'T', 110, N'Menyebut mekanisme tetap: tinjauan pascakejadian, berbagi pengetahuan, rotasi peran.', N'Mengandalkan semangat pribadi tanpa mekanisme apa pun.', N'Apa yang tetap berjalan waktu Anda sedang tidak ada?', N'{"1": "Bercerita sebagai pelaksana, bukan sebagai pengarah tim.", "2": "Menyebut peran memimpin, tapi tidak menjelaskan bagaimana ia mengambil keputusan.", "3": "Menjelaskan keputusan dan dampaknya pada tim.", "4": "Menjelaskan pertimbangan, komunikasi ke tim, dan hasil terukurnya.", "5": "Menunjukkan kematangan: mengakui trade-off, mengelola resistensi, dan mengembangkan orangnya."}', 107),
(N'bhv_inisi_inisiatif_awal', N'Perilaku', N'Inisiatif', N'BEHAVIORAL', N'RECOMMENDED', N'TEXTAREA', N'Ceritakan saat Anda mengerjakan sesuatu tanpa diminta karena Anda melihat itu perlu.', N'Untuk kandidat awal, inisiatif kecil pun berarti asalkan nyata.', NULL, NULL, NULL, NULL, NULL, 2, NULL, NULL, NULL, 'T', 'T', 110, N'Contoh konkret dan menyebut apa yang berubah karenanya.', N'Tidak bisa menyebut satu pun contoh.', N'Bagaimana tanggapan orang di sekitar Anda?', N'{"1": "Tidak menjawab situasi nyata; hanya opini umum atau normatif.", "2": "Menyebut situasi, tapi peran dirinya kabur dan hasilnya tidak jelas.", "3": "Situasi, tindakan, dan hasil tersampaikan cukup runtut.", "4": "Runtut dan spesifik; peran dirinya jelas, hasilnya terukur.", "5": "Sangat spesifik dan terukur; menyebut dampak, pembelajaran, dan apa yang akan ia ubah."}', 108),
(N'bhv_inisi_usulan_perbaikan', N'Perilaku', N'Inisiatif', N'BEHAVIORAL', N'RECOMMENDED', N'TEXTAREA', N'Ceritakan usulan perbaikan yang pernah Anda ajukan dan berhasil diterapkan.', N'Cari apakah ia menindaklanjuti sampai diterapkan atau berhenti di usulan.', NULL, NULL, NULL, NULL, NULL, 2, NULL, NULL, NULL, 'T', 'T', 110, N'Menyebut usulan, cara ia meyakinkan, dan hasil sesudah diterapkan.', N'Punya banyak ide tapi tidak satu pun yang sampai berjalan.', N'Apa hambatan terbesar sampai usulan itu diterima?', N'{"1": "Tidak menjawab situasi nyata; hanya opini umum atau normatif.", "2": "Menyebut situasi, tapi peran dirinya kabur dan hasilnya tidak jelas.", "3": "Situasi, tindakan, dan hasil tersampaikan cukup runtut.", "4": "Runtut dan spesifik; peran dirinya jelas, hasilnya terukur.", "5": "Sangat spesifik dan terukur; menyebut dampak, pembelajaran, dan apa yang akan ia ubah."}', 109),
(N'bhv_inisi_inisiatif_tim', N'Perilaku', N'Inisiatif', N'BEHAVIORAL', N'RECOMMENDED', N'TEXTAREA', N'Ceritakan program atau perbaikan yang Anda mulai sendiri di tim Anda.', N'Yang dinilai: apakah program itu masih berjalan sesudah ia meninggalkannya.', NULL, NULL, NULL, NULL, NULL, 2, NULL, NULL, NULL, 'T', 'T', 110, N'Program yang jelas, hasilnya terukur, dan tetap berjalan.', N'Program yang berhenti begitu ia berpindah.', N'Masih berjalan sampai sekarang?', N'{"1": "Bercerita sebagai pelaksana, bukan sebagai pengarah tim.", "2": "Menyebut peran memimpin, tapi tidak menjelaskan bagaimana ia mengambil keputusan.", "3": "Menjelaskan keputusan dan dampaknya pada tim.", "4": "Menjelaskan pertimbangan, komunikasi ke tim, dan hasil terukurnya.", "5": "Menunjukkan kematangan: mengakui trade-off, mengelola resistensi, dan mengembangkan orangnya."}', 110),
(N'bhv_inisi_inisiatif_strategis', N'Perilaku', N'Inisiatif', N'BEHAVIORAL', N'RECOMMENDED', N'TEXTAREA', N'Ceritakan inisiatif yang Anda dorong dan berdampak melampaui unit Anda sendiri.', N'Cari besarnya dampak dan cara ia mendapatkan dukungan lintas fungsi.', NULL, NULL, NULL, NULL, NULL, 2, NULL, NULL, NULL, 'T', 'T', 110, N'Dampak lintas unit yang terukur, dengan dukungan yang ia bangun sendiri.', N'Inisiatif yang berhenti di batas unitnya karena tidak ada yang mendukung.', N'Bagaimana Anda mendapat dukungan unit lain?', N'{"1": "Bercerita sebagai pelaksana, bukan sebagai pengarah tim.", "2": "Menyebut peran memimpin, tapi tidak menjelaskan bagaimana ia mengambil keputusan.", "3": "Menjelaskan keputusan dan dampaknya pada tim.", "4": "Menjelaskan pertimbangan, komunikasi ke tim, dan hasil terukurnya.", "5": "Menunjukkan kematangan: mengakui trade-off, mengelola resistensi, dan mengembangkan orangnya."}', 111),
(N'bhv_integ_jujur_sulit', N'Perilaku', N'Integritas', N'BEHAVIORAL', N'RECOMMENDED', N'TEXTAREA', N'Ceritakan saat Anda memilih jujur padahal itu merugikan Anda sendiri.', N'Contoh sederhana pun cukup, asal nyata.', NULL, NULL, NULL, NULL, NULL, 2, NULL, NULL, NULL, 'T', 'T', 110, N'Contoh nyata dan alasan yang jelas.', N'Tidak bisa menyebut contoh, atau contohnya justru menunjukkan sebaliknya.', N'Apa yang terjadi sesudahnya?', N'{"1": "Tidak menjawab situasi nyata; hanya opini umum atau normatif.", "2": "Menyebut situasi, tapi peran dirinya kabur dan hasilnya tidak jelas.", "3": "Situasi, tindakan, dan hasil tersampaikan cukup runtut.", "4": "Runtut dan spesifik; peran dirinya jelas, hasilnya terukur.", "5": "Sangat spesifik dan terukur; menyebut dampak, pembelajaran, dan apa yang akan ia ubah."}', 112),
(N'bhv_integ_diminta_menyimpang', N'Perilaku', N'Integritas', N'BEHAVIORAL', N'RECOMMENDED', N'TEXTAREA', N'Ceritakan saat Anda diminta melakukan sesuatu yang menurut Anda tidak tepat. Apa yang Anda lakukan?', N'Cari apakah ia menyampaikan keberatan lewat jalur yang benar.', NULL, NULL, NULL, NULL, NULL, 2, NULL, NULL, NULL, 'T', 'T', 110, N'Menyampaikan keberatan, menawarkan cara lain, dan meneruskan bila perlu.', N'Mengikuti saja, atau menolak tanpa menyampaikan alasannya.', N'Bagaimana hasil akhirnya?', N'{"1": "Tidak menjawab situasi nyata; hanya opini umum atau normatif.", "2": "Menyebut situasi, tapi peran dirinya kabur dan hasilnya tidak jelas.", "3": "Situasi, tindakan, dan hasil tersampaikan cukup runtut.", "4": "Runtut dan spesifik; peran dirinya jelas, hasilnya terukur.", "5": "Sangat spesifik dan terukur; menyebut dampak, pembelajaran, dan apa yang akan ia ubah."}', 113),
(N'bhv_integ_tegakkan_aturan', N'Perilaku', N'Integritas', N'BEHAVIORAL', N'RECOMMENDED', N'TEXTAREA', N'Ceritakan saat Anda harus menegakkan aturan pada anggota tim yang dekat dengan Anda.', N'Yang dinilai: konsistensi, dan cara ia menjaga hubungan sesudahnya.', NULL, NULL, NULL, NULL, NULL, 2, NULL, NULL, NULL, 'T', 'T', 110, N'Menegakkan secara konsisten, menjelaskan alasannya, dan menjaga martabat orangnya.', N'Memberi keringanan karena kedekatan, atau justru menghukum berlebihan agar terlihat adil.', N'Bagaimana hubungan Anda sesudahnya?', N'{"1": "Bercerita sebagai pelaksana, bukan sebagai pengarah tim.", "2": "Menyebut peran memimpin, tapi tidak menjelaskan bagaimana ia mengambil keputusan.", "3": "Menjelaskan keputusan dan dampaknya pada tim.", "4": "Menjelaskan pertimbangan, komunikasi ke tim, dan hasil terukurnya.", "5": "Menunjukkan kematangan: mengakui trade-off, mengelola resistensi, dan mengembangkan orangnya."}', 114),
(N'bhv_integ_benturan_kepentingan', N'Perilaku', N'Integritas', N'BEHAVIORAL', N'RECOMMENDED', N'TEXTAREA', N'Ceritakan saat Anda menghadapi benturan kepentingan dalam pengambilan keputusan.', N'Cari apakah ia mengungkapkannya lebih dulu dan menarik diri dari keputusannya.', NULL, NULL, NULL, NULL, NULL, 2, NULL, NULL, NULL, 'T', 'T', 110, N'Mengungkapkan sejak awal dan menyerahkan keputusannya ke pihak lain.', N'Menganggapnya bukan masalah karena merasa bisa objektif.', N'Kepada siapa Anda mengungkapkannya?', N'{"1": "Bercerita sebagai pelaksana, bukan sebagai pengarah tim.", "2": "Menyebut peran memimpin, tapi tidak menjelaskan bagaimana ia mengambil keputusan.", "3": "Menjelaskan keputusan dan dampaknya pada tim.", "4": "Menjelaskan pertimbangan, komunikasi ke tim, dan hasil terukurnya.", "5": "Menunjukkan kematangan: mengakui trade-off, mengelola resistensi, dan mengembangkan orangnya."}', 115),
(N'bhv_tahan_tekanan_tenggat', N'Perilaku', N'Daya Tahan', N'BEHAVIORAL', N'RECOMMENDED', N'TEXTAREA', N'Ceritakan saat Anda mengerjakan sesuatu di bawah tekanan waktu. Bagaimana Anda menghadapinya?', N'Yang dinilai cara mengelola diri, bukan besarnya tekanan.', NULL, NULL, NULL, NULL, NULL, 2, NULL, NULL, NULL, 'T', 'T', 110, N'Menyusun prioritas, meminta bantuan bila perlu, dan tetap menyelesaikannya.', N'Menyerah, atau menyelesaikannya dengan mengorbankan mutu tanpa memberi tahu siapa pun.', N'Apa yang paling membantu Anda saat itu?', N'{"1": "Tidak menjawab situasi nyata; hanya opini umum atau normatif.", "2": "Menyebut situasi, tapi peran dirinya kabur dan hasilnya tidak jelas.", "3": "Situasi, tindakan, dan hasil tersampaikan cukup runtut.", "4": "Runtut dan spesifik; peran dirinya jelas, hasilnya terukur.", "5": "Sangat spesifik dan terukur; menyebut dampak, pembelajaran, dan apa yang akan ia ubah."}', 116),
(N'bhv_tahan_beban_menumpuk', N'Perilaku', N'Daya Tahan', N'BEHAVIORAL', N'RECOMMENDED', N'TEXTAREA', N'Ceritakan periode paling berat dalam pekerjaan Anda. Bagaimana Anda melewatinya?', N'Cari cara ia menjaga diri sekaligus tetap menyampaikan keadaan sebenarnya ke atasan.', NULL, NULL, NULL, NULL, NULL, 2, NULL, NULL, NULL, 'T', 'T', 110, N'Menyusun prioritas ulang, berbicara terbuka ke atasan, dan menjaga daya tahannya.', N'Diam saja sampai kualitas kerjanya jatuh.', N'Kapan Anda memutuskan harus bicara ke atasan?', N'{"1": "Tidak menjawab situasi nyata; hanya opini umum atau normatif.", "2": "Menyebut situasi, tapi peran dirinya kabur dan hasilnya tidak jelas.", "3": "Situasi, tindakan, dan hasil tersampaikan cukup runtut.", "4": "Runtut dan spesifik; peran dirinya jelas, hasilnya terukur.", "5": "Sangat spesifik dan terukur; menyebut dampak, pembelajaran, dan apa yang akan ia ubah."}', 117),
(N'bhv_tahan_jaga_tim_tekanan', N'Perilaku', N'Daya Tahan', N'BEHAVIORAL', N'RECOMMENDED', N'TEXTAREA', N'Ceritakan saat tim Anda berada di bawah tekanan tinggi. Bagaimana Anda menjaga mereka tetap bekerja?', N'Yang dinilai: perlindungan pada tim dan kejujuran tentang keadaan.', NULL, NULL, NULL, NULL, NULL, 2, NULL, NULL, NULL, 'T', 'T', 110, N'Menyaring tekanan dari atas, menjelaskan keadaan apa adanya, dan menjaga prioritas tetap jelas.', N'Meneruskan seluruh tekanan apa adanya ke tim.', N'Apakah ada yang mengundurkan diri di periode itu?', N'{"1": "Bercerita sebagai pelaksana, bukan sebagai pengarah tim.", "2": "Menyebut peran memimpin, tapi tidak menjelaskan bagaimana ia mengambil keputusan.", "3": "Menjelaskan keputusan dan dampaknya pada tim.", "4": "Menjelaskan pertimbangan, komunikasi ke tim, dan hasil terukurnya.", "5": "Menunjukkan kematangan: mengakui trade-off, mengelola resistensi, dan mengembangkan orangnya."}', 118),
(N'bhv_tahan_krisis_organisasi', N'Perilaku', N'Daya Tahan', N'BEHAVIORAL', N'RECOMMENDED', N'TEXTAREA', N'Ceritakan saat unit atau perusahaan Anda menghadapi krisis. Apa peran Anda?', N'Cari ketenangan, kecepatan mengambil keputusan, dan kejujuran komunikasinya.', NULL, NULL, NULL, NULL, NULL, 2, NULL, NULL, NULL, 'T', 'T', 110, N'Menetapkan prioritas, memutuskan cepat, dan berkomunikasi jujur ke semua pihak.', N'Menyembunyikan keadaan sampai tidak bisa ditutupi lagi.', N'Keputusan tersulit apa yang harus Anda ambil?', N'{"1": "Bercerita sebagai pelaksana, bukan sebagai pengarah tim.", "2": "Menyebut peran memimpin, tapi tidak menjelaskan bagaimana ia mengambil keputusan.", "3": "Menjelaskan keputusan dan dampaknya pada tim.", "4": "Menjelaskan pertimbangan, komunikasi ke tim, dan hasil terukurnya.", "5": "Menunjukkan kematangan: mengakui trade-off, mengelola resistensi, dan mengembangkan orangnya."}', 119),
(N'bhv_custori_layani_sulit', N'Perilaku', N'Orientasi Pelanggan', N'BEHAVIORAL', N'RECOMMENDED', N'TEXTAREA', N'Ceritakan saat Anda melayani orang yang sulit dipuaskan. Bagaimana Anda menghadapinya?', N'Pelanggan internal pun sah — rekan divisi lain, dosen, panitia.', NULL, NULL, NULL, NULL, NULL, 2, NULL, NULL, NULL, 'T', 'T', 110, N'Tetap tenang, mencari kebutuhan sebenarnya, dan menawarkan jalan keluar.', N'Menganggap orangnya yang bermasalah tanpa mencoba memahami.', N'Apa yang sebenarnya ia butuhkan?', N'{"1": "Tidak menjawab situasi nyata; hanya opini umum atau normatif.", "2": "Menyebut situasi, tapi peran dirinya kabur dan hasilnya tidak jelas.", "3": "Situasi, tindakan, dan hasil tersampaikan cukup runtut.", "4": "Runtut dan spesifik; peran dirinya jelas, hasilnya terukur.", "5": "Sangat spesifik dan terukur; menyebut dampak, pembelajaran, dan apa yang akan ia ubah."}', 120);
