(N'ac2_serah_terima', N'Cara Kerja Bidang', N'Cara Kerja', N'BEHAVIORAL', N'OPTIONAL', N'TEXTAREA', N'Bagaimana Anda menyerahkan pekerjaan akuntansi Anda saat cuti panjang?', N'Menguji kerapian dokumentasi sekaligus kesediaan berbagi pengetahuan.', NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL, 'T', 'T', 85, N'Menyebut dokumentasi, penunjukan pengganti, dan penjelasan hal yang sedang berjalan.', N'Membiarkan semuanya menunggu sampai ia kembali.', N'Bisa beri contoh yang paling menggambarkan?', N'{"1": "Tidak menjawab situasi nyata; hanya opini umum atau normatif.", "2": "Menyebut situasi, tapi peran dirinya kabur dan hasilnya tidak jelas.", "3": "Situasi, tindakan, dan hasil tersampaikan cukup runtut.", "4": "Runtut dan spesifik; peran dirinya jelas, hasilnya terukur.", "5": "Sangat spesifik dan terukur; menyebut dampak, pembelajaran, dan apa yang akan ia ubah."}', 659),
(N'ac2_salah_paham', N'Cara Kerja Bidang', N'Persepsi', N'EXPERIENCE', N'OPTIONAL', N'TEXTAREA', N'Apa yang menurut Anda paling sering disalahpahami orang di luar bidang akuntansi tentang pekerjaan Anda?', N'Jawaban yang bagus menunjukkan ia sudah cukup lama merasakan gesekannya.', NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL, 'T', 'T', 85, N'Menyebut salah paham yang spesifik dan bagaimana ia menjelaskannya.', N'Tidak pernah merasa ada salah paham.', N'Bisa beri contoh yang paling menggambarkan?', N'{"1": "Tidak menjawab situasi nyata; hanya opini umum atau normatif.", "2": "Menyebut situasi, tapi peran dirinya kabur dan hasilnya tidak jelas.", "3": "Situasi, tindakan, dan hasil tersampaikan cukup runtut.", "4": "Runtut dan spesifik; peran dirinya jelas, hasilnya terukur.", "5": "Sangat spesifik dan terukur; menyebut dampak, pembelajaran, dan apa yang akan ia ubah."}', 660);
INSERT INTO dbo.NWC_Stage_Bank (Kode, Kelompok, Sub_Kelompok, Jenis, Prioritas, Tipe, Label, Bantuan, Opsi, Skala_Min, Skala_Max, Label_Min, Label_Max, Bobot_Bawaan, Knockout_Operator, Knockout_Nilai, Knockout_Pesan, Flag_Wajib_Bawaan, Flag_Catatan_Bawaan, Durasi_Detik, Jawaban_Diharapkan, Red_Flag, Pertanyaan_Lanjutan, Kriteria_Nilai, Urutan) VALUES
(N'ac2_unggul_vs_cukup', N'Cara Kerja Bidang', N'Standar', N'EXPERIENCE', N'OPTIONAL', N'TEXTAREA', N'Menurut Anda, apa yang membedakan orang yang unggul di bidang akuntansi dari yang sekadar memenuhi syarat?', N'Jawabannya mengungkap standar pribadinya — dan biasanya juga mengungkap di mana ia menempatkan dirinya.', NULL, NULL, NULL, NULL, NULL, 2, NULL, NULL, NULL, 'T', 'T', 85, N'Menyebut pembeda yang spesifik dan bisa diamati.', N'Menyebut sifat umum seperti "rajin" dan "teliti" saja.', N'Bisa beri contoh yang paling menggambarkan?', N'{"1": "Tidak menjawab situasi nyata; hanya opini umum atau normatif.", "2": "Menyebut situasi, tapi peran dirinya kabur dan hasilnya tidak jelas.", "3": "Situasi, tindakan, dan hasil tersampaikan cukup runtut.", "4": "Runtut dan spesifik; peran dirinya jelas, hasilnya terukur.", "5": "Sangat spesifik dan terukur; menyebut dampak, pembelajaran, dan apa yang akan ia ubah."}', 661),
(N'ac2_rencana_90_hari', N'Cara Kerja Bidang', N'Kontribusi', N'SITUATIONAL', N'RECOMMENDED', N'TEXTAREA', N'Kalau diterima di bidang akuntansi di sini, apa yang akan Anda kerjakan di 90 hari pertama?', N'Menguji pemahaman posisi sekaligus realisme. Pendatang baru yang menjanjikan perombakan besar biasanya belum paham.', NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL, 'T', 'T', 85, N'Menyebut tahapan yang masuk akal: memahami dulu, lalu memperbaiki yang jelas.', N'Menjanjikan perubahan besar sebelum memahami keadaannya.', N'Bisa beri contoh yang paling menggambarkan?', N'{"1": "Tidak menjawab situasi nyata; hanya opini umum atau normatif.", "2": "Menyebut situasi, tapi peran dirinya kabur dan hasilnya tidak jelas.", "3": "Situasi, tindakan, dan hasil tersampaikan cukup runtut.", "4": "Runtut dan spesifik; peran dirinya jelas, hasilnya terukur.", "5": "Sangat spesifik dan terukur; menyebut dampak, pembelajaran, dan apa yang akan ia ubah."}', 662),
(N'ac2_struktur_bidang', N'Cara Kerja Bidang', N'Lingkup', N'EXPERIENCE', N'OPTIONAL', N'TEXTAREA', N'Bagaimana struktur tim akuntansi yang Anda pimpin, dan bagaimana pembagian perannya?', N'Struktur mengungkap lingkup sebenarnya lebih jujur daripada nama jabatan.', NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL, 'T', 'T', 85, N'Menyebut jumlah orang, pembagian peran, dan alasan pembagiannya.', N'Tidak bisa menjelaskan pembagian peran di timnya sendiri.', N'Bisa beri contoh yang paling menggambarkan?', N'{"1": "Bercerita sebagai pelaksana, bukan sebagai pengarah tim.", "2": "Menyebut peran memimpin, tapi tidak menjelaskan bagaimana ia mengambil keputusan.", "3": "Menjelaskan keputusan dan dampaknya pada tim.", "4": "Menjelaskan pertimbangan, komunikasi ke tim, dan hasil terukurnya.", "5": "Menunjukkan kematangan: mengakui trade-off, mengelola resistensi, dan mengembangkan orangnya."}', 663),
(N'ac2_lapor_kinerja_bidang', N'Cara Kerja Bidang', N'Pelaporan', N'EXPERIENCE', N'OPTIONAL', N'TEXTAREA', N'Angka akuntansi apa yang rutin Anda laporkan ke atasan, dan seberapa sering?', N'Cari irama tetap, bukan laporan saat diminta.', NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL, 'T', 'T', 85, N'Menyebut angka spesifik dan irama pelaporannya.', N'Melapor hanya saat ada masalah.', N'Bisa beri contoh yang paling menggambarkan?', N'{"1": "Bercerita sebagai pelaksana, bukan sebagai pengarah tim.", "2": "Menyebut peran memimpin, tapi tidak menjelaskan bagaimana ia mengambil keputusan.", "3": "Menjelaskan keputusan dan dampaknya pada tim.", "4": "Menjelaskan pertimbangan, komunikasi ke tim, dan hasil terukurnya.", "5": "Menunjukkan kematangan: mengakui trade-off, mengelola resistensi, dan mengembangkan orangnya."}', 664),
(N'ac2_rekrut_bidang', N'Cara Kerja Bidang', N'Tim', N'BEHAVIORAL', N'OPTIONAL', N'TEXTAREA', N'Apa yang Anda cari saat merekrut orang untuk tim akuntansi Anda?', N'Kriteria yang ia sebut mengungkap apa yang menurutnya menentukan di bidang itu.', NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL, 'T', 'T', 85, N'Menyebut kriteria kemampuan sekaligus cara kerja, dengan alasan yang jelas.', N'Hanya mencari pengalaman di perusahaan sejenis.', N'Bisa beri contoh yang paling menggambarkan?', N'{"1": "Bercerita sebagai pelaksana, bukan sebagai pengarah tim.", "2": "Menyebut peran memimpin, tapi tidak menjelaskan bagaimana ia mengambil keputusan.", "3": "Menjelaskan keputusan dan dampaknya pada tim.", "4": "Menjelaskan pertimbangan, komunikasi ke tim, dan hasil terukurnya.", "5": "Menunjukkan kematangan: mengakui trade-off, mengelola resistensi, dan mengembangkan orangnya."}', 665),
(N'ac2_sumber_daya_bidang', N'Cara Kerja Bidang', N'Sumber Daya', N'EXPERIENCE', N'OPTIONAL', N'TEXTAREA', N'Sumber daya apa yang paling sering kurang di bidang akuntansi Anda, dan bagaimana Anda menyiasatinya?', N'Cari kemampuan bekerja dalam keterbatasan, bukan daftar keluhan.', NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL, 'T', 'T', 85, N'Menyebut keterbatasan nyata dan cara ia menyiasatinya.', N'Hanya mengeluhkan kekurangan tanpa upaya apa pun.', N'Bisa beri contoh yang paling menggambarkan?', N'{"1": "Bercerita sebagai pelaksana, bukan sebagai pengarah tim.", "2": "Menyebut peran memimpin, tapi tidak menjelaskan bagaimana ia mengambil keputusan.", "3": "Menjelaskan keputusan dan dampaknya pada tim.", "4": "Menjelaskan pertimbangan, komunikasi ke tim, dan hasil terukurnya.", "5": "Menunjukkan kematangan: mengakui trade-off, mengelola resistensi, dan mengembangkan orangnya."}', 666),
(N'ac2_perbaikan_bidang', N'Cara Kerja Bidang', N'Perbaikan', N'BEHAVIORAL', N'OPTIONAL', N'TEXTAREA', N'Perbaikan apa yang paling ingin Anda lakukan di bidang akuntansi bila diberi kewenangan penuh?', N'Mengungkap cara pandangnya tentang bidang itu, sekaligus apakah ia sudah memikirkannya.', NULL, NULL, NULL, NULL, NULL, 2, NULL, NULL, NULL, 'T', 'T', 85, N'Menyebut perbaikan spesifik beserta alasan dan perkiraan dampaknya.', N'Tidak punya gagasan perbaikan sama sekali.', N'Bisa beri contoh yang paling menggambarkan?', N'{"1": "Bercerita sebagai pelaksana, bukan sebagai pengarah tim.", "2": "Menyebut peran memimpin, tapi tidak menjelaskan bagaimana ia mengambil keputusan.", "3": "Menjelaskan keputusan dan dampaknya pada tim.", "4": "Menjelaskan pertimbangan, komunikasi ke tim, dan hasil terukurnya.", "5": "Menunjukkan kematangan: mengakui trade-off, mengelola resistensi, dan mengembangkan orangnya."}', 667),
(N'ac2_bekal_kuliah', N'Cara Kerja Bidang', N'Kesiapan', N'EXPERIENCE', N'OPTIONAL', N'TEXTAREA', N'Bagian mana dari pendidikan Anda yang paling membekali untuk bidang akuntansi?', N'Untuk kandidat awal, kaitan pendidikan dengan bidangnya adalah bukti kesiapan yang tersedia.', NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL, 'T', 'T', 85, N'Menyebut mata kuliah, proyek, atau praktik yang benar-benar relevan.', N'Tidak bisa menghubungkan pendidikannya dengan bidang yang dilamar.', N'Bisa beri contoh yang paling menggambarkan?', N'{"1": "Tidak menjawab situasi nyata; hanya opini umum atau normatif.", "2": "Menyebut situasi, tapi peran dirinya kabur dan hasilnya tidak jelas.", "3": "Situasi, tindakan, dan hasil tersampaikan cukup runtut.", "4": "Runtut dan spesifik; peran dirinya jelas, hasilnya terukur.", "5": "Sangat spesifik dan terukur; menyebut dampak, pembelajaran, dan apa yang akan ia ubah."}', 668),
(N'ac2_tarik_bidang', N'Cara Kerja Bidang', N'Motivasi', N'MOTIVATION', N'OPTIONAL', N'TEXTAREA', N'Apa yang membuat Anda tertarik pada bidang akuntansi dibanding bidang lain?', N'Ketertarikan yang bisa dijelaskan lebih bertahan daripada yang tidak.', NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL, 'T', 'T', 85, N'Menyebut alasan spesifik yang terkait isi pekerjaannya.', N'Menjawab karena kebetulan ada lowongannya.', N'Bisa beri contoh yang paling menggambarkan?', N'{"1": "Tidak menjawab situasi nyata; hanya opini umum atau normatif.", "2": "Menyebut situasi, tapi peran dirinya kabur dan hasilnya tidak jelas.", "3": "Situasi, tindakan, dan hasil tersampaikan cukup runtut.", "4": "Runtut dan spesifik; peran dirinya jelas, hasilnya terukur.", "5": "Sangat spesifik dan terukur; menyebut dampak, pembelajaran, dan apa yang akan ia ubah."}', 669),
