(N'pr2_rencana_90_hari', N'Cara Kerja Bidang', N'Kontribusi', N'SITUATIONAL', N'RECOMMENDED', N'TEXTAREA', N'Kalau diterima di bidang pengadaan di sini, apa yang akan Anda kerjakan di 90 hari pertama?', N'Menguji pemahaman posisi sekaligus realisme. Pendatang baru yang menjanjikan perombakan besar biasanya belum paham.', NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL, 'T', 'T', 85, N'Menyebut tahapan yang masuk akal: memahami dulu, lalu memperbaiki yang jelas.', N'Menjanjikan perubahan besar sebelum memahami keadaannya.', N'Bisa beri contoh yang paling menggambarkan?', N'{"1": "Tidak menjawab situasi nyata; hanya opini umum atau normatif.", "2": "Menyebut situasi, tapi peran dirinya kabur dan hasilnya tidak jelas.", "3": "Situasi, tindakan, dan hasil tersampaikan cukup runtut.", "4": "Runtut dan spesifik; peran dirinya jelas, hasilnya terukur.", "5": "Sangat spesifik dan terukur; menyebut dampak, pembelajaran, dan apa yang akan ia ubah."}', 716),
(N'pr2_struktur_bidang', N'Cara Kerja Bidang', N'Lingkup', N'EXPERIENCE', N'OPTIONAL', N'TEXTAREA', N'Bagaimana struktur tim pengadaan yang Anda pimpin, dan bagaimana pembagian perannya?', N'Struktur mengungkap lingkup sebenarnya lebih jujur daripada nama jabatan.', NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL, 'T', 'T', 85, N'Menyebut jumlah orang, pembagian peran, dan alasan pembagiannya.', N'Tidak bisa menjelaskan pembagian peran di timnya sendiri.', N'Bisa beri contoh yang paling menggambarkan?', N'{"1": "Bercerita sebagai pelaksana, bukan sebagai pengarah tim.", "2": "Menyebut peran memimpin, tapi tidak menjelaskan bagaimana ia mengambil keputusan.", "3": "Menjelaskan keputusan dan dampaknya pada tim.", "4": "Menjelaskan pertimbangan, komunikasi ke tim, dan hasil terukurnya.", "5": "Menunjukkan kematangan: mengakui trade-off, mengelola resistensi, dan mengembangkan orangnya."}', 717),
(N'pr2_lapor_kinerja_bidang', N'Cara Kerja Bidang', N'Pelaporan', N'EXPERIENCE', N'OPTIONAL', N'TEXTAREA', N'Angka pengadaan apa yang rutin Anda laporkan ke atasan, dan seberapa sering?', N'Cari irama tetap, bukan laporan saat diminta.', NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL, 'T', 'T', 85, N'Menyebut angka spesifik dan irama pelaporannya.', N'Melapor hanya saat ada masalah.', N'Bisa beri contoh yang paling menggambarkan?', N'{"1": "Bercerita sebagai pelaksana, bukan sebagai pengarah tim.", "2": "Menyebut peran memimpin, tapi tidak menjelaskan bagaimana ia mengambil keputusan.", "3": "Menjelaskan keputusan dan dampaknya pada tim.", "4": "Menjelaskan pertimbangan, komunikasi ke tim, dan hasil terukurnya.", "5": "Menunjukkan kematangan: mengakui trade-off, mengelola resistensi, dan mengembangkan orangnya."}', 718),
(N'pr2_rekrut_bidang', N'Cara Kerja Bidang', N'Tim', N'BEHAVIORAL', N'OPTIONAL', N'TEXTAREA', N'Apa yang Anda cari saat merekrut orang untuk tim pengadaan Anda?', N'Kriteria yang ia sebut mengungkap apa yang menurutnya menentukan di bidang itu.', NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL, 'T', 'T', 85, N'Menyebut kriteria kemampuan sekaligus cara kerja, dengan alasan yang jelas.', N'Hanya mencari pengalaman di perusahaan sejenis.', N'Bisa beri contoh yang paling menggambarkan?', N'{"1": "Bercerita sebagai pelaksana, bukan sebagai pengarah tim.", "2": "Menyebut peran memimpin, tapi tidak menjelaskan bagaimana ia mengambil keputusan.", "3": "Menjelaskan keputusan dan dampaknya pada tim.", "4": "Menjelaskan pertimbangan, komunikasi ke tim, dan hasil terukurnya.", "5": "Menunjukkan kematangan: mengakui trade-off, mengelola resistensi, dan mengembangkan orangnya."}', 719),
(N'pr2_sumber_daya_bidang', N'Cara Kerja Bidang', N'Sumber Daya', N'EXPERIENCE', N'OPTIONAL', N'TEXTAREA', N'Sumber daya apa yang paling sering kurang di bidang pengadaan Anda, dan bagaimana Anda menyiasatinya?', N'Cari kemampuan bekerja dalam keterbatasan, bukan daftar keluhan.', NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL, 'T', 'T', 85, N'Menyebut keterbatasan nyata dan cara ia menyiasatinya.', N'Hanya mengeluhkan kekurangan tanpa upaya apa pun.', N'Bisa beri contoh yang paling menggambarkan?', N'{"1": "Bercerita sebagai pelaksana, bukan sebagai pengarah tim.", "2": "Menyebut peran memimpin, tapi tidak menjelaskan bagaimana ia mengambil keputusan.", "3": "Menjelaskan keputusan dan dampaknya pada tim.", "4": "Menjelaskan pertimbangan, komunikasi ke tim, dan hasil terukurnya.", "5": "Menunjukkan kematangan: mengakui trade-off, mengelola resistensi, dan mengembangkan orangnya."}', 720);
