(N'qa2_unggul_vs_cukup', N'Cara Kerja Bidang', N'Standar', N'EXPERIENCE', N'OPTIONAL', N'TEXTAREA', N'Menurut Anda, apa yang membedakan orang yang unggul di bidang penjaminan mutu dari yang sekadar memenuhi syarat?', N'Jawabannya mengungkap standar pribadinya — dan biasanya juga mengungkap di mana ia menempatkan dirinya.', NULL, NULL, NULL, NULL, NULL, 2, NULL, NULL, NULL, 'T', 'T', 85, N'Menyebut pembeda yang spesifik dan bisa diamati.', N'Menyebut sifat umum seperti "rajin" dan "teliti" saja.', N'Bisa beri contoh yang paling menggambarkan?', N'{"1": "Tidak menjawab situasi nyata; hanya opini umum atau normatif.", "2": "Menyebut situasi, tapi peran dirinya kabur dan hasilnya tidak jelas.", "3": "Situasi, tindakan, dan hasil tersampaikan cukup runtut.", "4": "Runtut dan spesifik; peran dirinya jelas, hasilnya terukur.", "5": "Sangat spesifik dan terukur; menyebut dampak, pembelajaran, dan apa yang akan ia ubah."}', 841),
(N'qa2_rencana_90_hari', N'Cara Kerja Bidang', N'Kontribusi', N'SITUATIONAL', N'RECOMMENDED', N'TEXTAREA', N'Kalau diterima di bidang penjaminan mutu di sini, apa yang akan Anda kerjakan di 90 hari pertama?', N'Menguji pemahaman posisi sekaligus realisme. Pendatang baru yang menjanjikan perombakan besar biasanya belum paham.', NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL, 'T', 'T', 85, N'Menyebut tahapan yang masuk akal: memahami dulu, lalu memperbaiki yang jelas.', N'Menjanjikan perubahan besar sebelum memahami keadaannya.', N'Bisa beri contoh yang paling menggambarkan?', N'{"1": "Tidak menjawab situasi nyata; hanya opini umum atau normatif.", "2": "Menyebut situasi, tapi peran dirinya kabur dan hasilnya tidak jelas.", "3": "Situasi, tindakan, dan hasil tersampaikan cukup runtut.", "4": "Runtut dan spesifik; peran dirinya jelas, hasilnya terukur.", "5": "Sangat spesifik dan terukur; menyebut dampak, pembelajaran, dan apa yang akan ia ubah."}', 842),
(N'qa2_struktur_bidang', N'Cara Kerja Bidang', N'Lingkup', N'EXPERIENCE', N'OPTIONAL', N'TEXTAREA', N'Bagaimana struktur tim penjaminan mutu yang Anda pimpin, dan bagaimana pembagian perannya?', N'Struktur mengungkap lingkup sebenarnya lebih jujur daripada nama jabatan.', NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL, 'T', 'T', 85, N'Menyebut jumlah orang, pembagian peran, dan alasan pembagiannya.', N'Tidak bisa menjelaskan pembagian peran di timnya sendiri.', N'Bisa beri contoh yang paling menggambarkan?', N'{"1": "Bercerita sebagai pelaksana, bukan sebagai pengarah tim.", "2": "Menyebut peran memimpin, tapi tidak menjelaskan bagaimana ia mengambil keputusan.", "3": "Menjelaskan keputusan dan dampaknya pada tim.", "4": "Menjelaskan pertimbangan, komunikasi ke tim, dan hasil terukurnya.", "5": "Menunjukkan kematangan: mengakui trade-off, mengelola resistensi, dan mengembangkan orangnya."}', 843),
(N'qa2_lapor_kinerja_bidang', N'Cara Kerja Bidang', N'Pelaporan', N'EXPERIENCE', N'OPTIONAL', N'TEXTAREA', N'Angka penjaminan mutu apa yang rutin Anda laporkan ke atasan, dan seberapa sering?', N'Cari irama tetap, bukan laporan saat diminta.', NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL, 'T', 'T', 85, N'Menyebut angka spesifik dan irama pelaporannya.', N'Melapor hanya saat ada masalah.', N'Bisa beri contoh yang paling menggambarkan?', N'{"1": "Bercerita sebagai pelaksana, bukan sebagai pengarah tim.", "2": "Menyebut peran memimpin, tapi tidak menjelaskan bagaimana ia mengambil keputusan.", "3": "Menjelaskan keputusan dan dampaknya pada tim.", "4": "Menjelaskan pertimbangan, komunikasi ke tim, dan hasil terukurnya.", "5": "Menunjukkan kematangan: mengakui trade-off, mengelola resistensi, dan mengembangkan orangnya."}', 844),
(N'qa2_rekrut_bidang', N'Cara Kerja Bidang', N'Tim', N'BEHAVIORAL', N'OPTIONAL', N'TEXTAREA', N'Apa yang Anda cari saat merekrut orang untuk tim penjaminan mutu Anda?', N'Kriteria yang ia sebut mengungkap apa yang menurutnya menentukan di bidang itu.', NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL, 'T', 'T', 85, N'Menyebut kriteria kemampuan sekaligus cara kerja, dengan alasan yang jelas.', N'Hanya mencari pengalaman di perusahaan sejenis.', N'Bisa beri contoh yang paling menggambarkan?', N'{"1": "Bercerita sebagai pelaksana, bukan sebagai pengarah tim.", "2": "Menyebut peran memimpin, tapi tidak menjelaskan bagaimana ia mengambil keputusan.", "3": "Menjelaskan keputusan dan dampaknya pada tim.", "4": "Menjelaskan pertimbangan, komunikasi ke tim, dan hasil terukurnya.", "5": "Menunjukkan kematangan: mengakui trade-off, mengelola resistensi, dan mengembangkan orangnya."}', 845),
