(N'cs2_cukup_baik', N'Cara Kerja Bidang', N'Mutu', N'EXPERIENCE', N'OPTIONAL', N'TEXTAREA', N'Di bidang layanan pelanggan, dari mana Anda tahu hasil pekerjaan Anda sudah cukup baik?', N'Cari patokan yang bisa disebut, bukan perasaan.', NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL, 'T', 'T', 85, N'Menyebut standar, ukuran, atau pemeriksaan yang ia jadikan patokan.', N'Mengandalkan perasaan tanpa patokan apa pun.', N'Bisa beri contoh yang paling menggambarkan?', N'{"1": "Tidak menjawab situasi nyata; hanya opini umum atau normatif.", "2": "Menyebut situasi, tapi peran dirinya kabur dan hasilnya tidak jelas.", "3": "Situasi, tindakan, dan hasil tersampaikan cukup runtut.", "4": "Runtut dan spesifik; peran dirinya jelas, hasilnya terukur.", "5": "Sangat spesifik dan terukur; menyebut dampak, pembelajaran, dan apa yang akan ia ubah."}', 891),
(N'cs2_permintaan_mendadak', N'Cara Kerja Bidang', N'Cara Kerja', N'SITUATIONAL', N'OPTIONAL', N'TEXTAREA', N'Apa yang Anda lakukan ketika ada permintaan layanan pelanggan yang mendadak, padahal pekerjaan terjadwal Anda sudah penuh?', N'Cari negosiasi prioritas, bukan menyanggupi semuanya lalu gagal.', NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL, 'T', 'T', 85, N'Menilai kegentingan, membicarakan prioritas, dan menyepakati apa yang digeser.', N'Menyanggupi semuanya lalu diam-diam menunda salah satunya.', N'Bisa beri contoh yang paling menggambarkan?', N'{"1": "Tidak menjawab situasi nyata; hanya opini umum atau normatif.", "2": "Menyebut situasi, tapi peran dirinya kabur dan hasilnya tidak jelas.", "3": "Situasi, tindakan, dan hasil tersampaikan cukup runtut.", "4": "Runtut dan spesifik; peran dirinya jelas, hasilnya terukur.", "5": "Sangat spesifik dan terukur; menyebut dampak, pembelajaran, dan apa yang akan ia ubah."}', 892),
(N'cs2_serah_terima', N'Cara Kerja Bidang', N'Cara Kerja', N'BEHAVIORAL', N'OPTIONAL', N'TEXTAREA', N'Bagaimana Anda menyerahkan pekerjaan layanan pelanggan Anda saat cuti panjang?', N'Menguji kerapian dokumentasi sekaligus kesediaan berbagi pengetahuan.', NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL, 'T', 'T', 85, N'Menyebut dokumentasi, penunjukan pengganti, dan penjelasan hal yang sedang berjalan.', N'Membiarkan semuanya menunggu sampai ia kembali.', N'Bisa beri contoh yang paling menggambarkan?', N'{"1": "Tidak menjawab situasi nyata; hanya opini umum atau normatif.", "2": "Menyebut situasi, tapi peran dirinya kabur dan hasilnya tidak jelas.", "3": "Situasi, tindakan, dan hasil tersampaikan cukup runtut.", "4": "Runtut dan spesifik; peran dirinya jelas, hasilnya terukur.", "5": "Sangat spesifik dan terukur; menyebut dampak, pembelajaran, dan apa yang akan ia ubah."}', 893),
(N'cs2_salah_paham', N'Cara Kerja Bidang', N'Persepsi', N'EXPERIENCE', N'OPTIONAL', N'TEXTAREA', N'Apa yang menurut Anda paling sering disalahpahami orang di luar bidang layanan pelanggan tentang pekerjaan Anda?', N'Jawaban yang bagus menunjukkan ia sudah cukup lama merasakan gesekannya.', NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL, 'T', 'T', 85, N'Menyebut salah paham yang spesifik dan bagaimana ia menjelaskannya.', N'Tidak pernah merasa ada salah paham.', N'Bisa beri contoh yang paling menggambarkan?', N'{"1": "Tidak menjawab situasi nyata; hanya opini umum atau normatif.", "2": "Menyebut situasi, tapi peran dirinya kabur dan hasilnya tidak jelas.", "3": "Situasi, tindakan, dan hasil tersampaikan cukup runtut.", "4": "Runtut dan spesifik; peran dirinya jelas, hasilnya terukur.", "5": "Sangat spesifik dan terukur; menyebut dampak, pembelajaran, dan apa yang akan ia ubah."}', 894),
(N'cs2_unggul_vs_cukup', N'Cara Kerja Bidang', N'Standar', N'EXPERIENCE', N'OPTIONAL', N'TEXTAREA', N'Menurut Anda, apa yang membedakan orang yang unggul di bidang layanan pelanggan dari yang sekadar memenuhi syarat?', N'Jawabannya mengungkap standar pribadinya — dan biasanya juga mengungkap di mana ia menempatkan dirinya.', NULL, NULL, NULL, NULL, NULL, 2, NULL, NULL, NULL, 'T', 'T', 85, N'Menyebut pembeda yang spesifik dan bisa diamati.', N'Menyebut sifat umum seperti "rajin" dan "teliti" saja.', N'Bisa beri contoh yang paling menggambarkan?', N'{"1": "Tidak menjawab situasi nyata; hanya opini umum atau normatif.", "2": "Menyebut situasi, tapi peran dirinya kabur dan hasilnya tidak jelas.", "3": "Situasi, tindakan, dan hasil tersampaikan cukup runtut.", "4": "Runtut dan spesifik; peran dirinya jelas, hasilnya terukur.", "5": "Sangat spesifik dan terukur; menyebut dampak, pembelajaran, dan apa yang akan ia ubah."}', 895),
(N'cs2_rencana_90_hari', N'Cara Kerja Bidang', N'Kontribusi', N'SITUATIONAL', N'RECOMMENDED', N'TEXTAREA', N'Kalau diterima di bidang layanan pelanggan di sini, apa yang akan Anda kerjakan di 90 hari pertama?', N'Menguji pemahaman posisi sekaligus realisme. Pendatang baru yang menjanjikan perombakan besar biasanya belum paham.', NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL, 'T', 'T', 85, N'Menyebut tahapan yang masuk akal: memahami dulu, lalu memperbaiki yang jelas.', N'Menjanjikan perubahan besar sebelum memahami keadaannya.', N'Bisa beri contoh yang paling menggambarkan?', N'{"1": "Tidak menjawab situasi nyata; hanya opini umum atau normatif.", "2": "Menyebut situasi, tapi peran dirinya kabur dan hasilnya tidak jelas.", "3": "Situasi, tindakan, dan hasil tersampaikan cukup runtut.", "4": "Runtut dan spesifik; peran dirinya jelas, hasilnya terukur.", "5": "Sangat spesifik dan terukur; menyebut dampak, pembelajaran, dan apa yang akan ia ubah."}', 896),
(N'cs2_struktur_bidang', N'Cara Kerja Bidang', N'Lingkup', N'EXPERIENCE', N'OPTIONAL', N'TEXTAREA', N'Bagaimana struktur tim layanan pelanggan yang Anda pimpin, dan bagaimana pembagian perannya?', N'Struktur mengungkap lingkup sebenarnya lebih jujur daripada nama jabatan.', NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL, 'T', 'T', 85, N'Menyebut jumlah orang, pembagian peran, dan alasan pembagiannya.', N'Tidak bisa menjelaskan pembagian peran di timnya sendiri.', N'Bisa beri contoh yang paling menggambarkan?', N'{"1": "Bercerita sebagai pelaksana, bukan sebagai pengarah tim.", "2": "Menyebut peran memimpin, tapi tidak menjelaskan bagaimana ia mengambil keputusan.", "3": "Menjelaskan keputusan dan dampaknya pada tim.", "4": "Menjelaskan pertimbangan, komunikasi ke tim, dan hasil terukurnya.", "5": "Menunjukkan kematangan: mengakui trade-off, mengelola resistensi, dan mengembangkan orangnya."}', 897),
(N'cs2_lapor_kinerja_bidang', N'Cara Kerja Bidang', N'Pelaporan', N'EXPERIENCE', N'OPTIONAL', N'TEXTAREA', N'Angka layanan pelanggan apa yang rutin Anda laporkan ke atasan, dan seberapa sering?', N'Cari irama tetap, bukan laporan saat diminta.', NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL, 'T', 'T', 85, N'Menyebut angka spesifik dan irama pelaporannya.', N'Melapor hanya saat ada masalah.', N'Bisa beri contoh yang paling menggambarkan?', N'{"1": "Bercerita sebagai pelaksana, bukan sebagai pengarah tim.", "2": "Menyebut peran memimpin, tapi tidak menjelaskan bagaimana ia mengambil keputusan.", "3": "Menjelaskan keputusan dan dampaknya pada tim.", "4": "Menjelaskan pertimbangan, komunikasi ke tim, dan hasil terukurnya.", "5": "Menunjukkan kematangan: mengakui trade-off, mengelola resistensi, dan mengembangkan orangnya."}', 898),
(N'cs2_rekrut_bidang', N'Cara Kerja Bidang', N'Tim', N'BEHAVIORAL', N'OPTIONAL', N'TEXTAREA', N'Apa yang Anda cari saat merekrut orang untuk tim layanan pelanggan Anda?', N'Kriteria yang ia sebut mengungkap apa yang menurutnya menentukan di bidang itu.', NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL, 'T', 'T', 85, N'Menyebut kriteria kemampuan sekaligus cara kerja, dengan alasan yang jelas.', N'Hanya mencari pengalaman di perusahaan sejenis.', N'Bisa beri contoh yang paling menggambarkan?', N'{"1": "Bercerita sebagai pelaksana, bukan sebagai pengarah tim.", "2": "Menyebut peran memimpin, tapi tidak menjelaskan bagaimana ia mengambil keputusan.", "3": "Menjelaskan keputusan dan dampaknya pada tim.", "4": "Menjelaskan pertimbangan, komunikasi ke tim, dan hasil terukurnya.", "5": "Menunjukkan kematangan: mengakui trade-off, mengelola resistensi, dan mengembangkan orangnya."}', 899),
(N'cs2_sumber_daya_bidang', N'Cara Kerja Bidang', N'Sumber Daya', N'EXPERIENCE', N'OPTIONAL', N'TEXTAREA', N'Sumber daya apa yang paling sering kurang di bidang layanan pelanggan Anda, dan bagaimana Anda menyiasatinya?', N'Cari kemampuan bekerja dalam keterbatasan, bukan daftar keluhan.', NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL, 'T', 'T', 85, N'Menyebut keterbatasan nyata dan cara ia menyiasatinya.', N'Hanya mengeluhkan kekurangan tanpa upaya apa pun.', N'Bisa beri contoh yang paling menggambarkan?', N'{"1": "Bercerita sebagai pelaksana, bukan sebagai pengarah tim.", "2": "Menyebut peran memimpin, tapi tidak menjelaskan bagaimana ia mengambil keputusan.", "3": "Menjelaskan keputusan dan dampaknya pada tim.", "4": "Menjelaskan pertimbangan, komunikasi ke tim, dan hasil terukurnya.", "5": "Menunjukkan kematangan: mengakui trade-off, mengelola resistensi, dan mengembangkan orangnya."}', 900);
INSERT INTO dbo.NWC_Stage_Bank (Kode, Kelompok, Sub_Kelompok, Jenis, Prioritas, Tipe, Label, Bantuan, Opsi, Skala_Min, Skala_Max, Label_Min, Label_Max, Bobot_Bawaan, Knockout_Operator, Knockout_Nilai, Knockout_Pesan, Flag_Wajib_Bawaan, Flag_Catatan_Bawaan, Durasi_Detik, Jawaban_Diharapkan, Red_Flag, Pertanyaan_Lanjutan, Kriteria_Nilai, Urutan) VALUES
